<?php require __DIR__.'/app-bootstrap.php'; $artists=$pdo->query("SELECT a.*,COUNT(DISTINCT t.id) track_count FROM artists a LEFT JOIN track_artists ta ON ta.artist_id=a.id LEFT JOIN tracks t ON t.id=ta.track_id AND t.active=1 GROUP BY a.id ORDER BY a.name")->fetchAll(); layout_header('Artists'); ?><div class="section-title"><div><span class="kicker">THE PEOPLE BEHIND THE MUSIC</span><h1>Artists</h1></div></div><div class="artist-grid"><?php foreach($artists as $a): ?><a class="panel artist" href="<?=e(url('artists/'.artist_public_slug($a)))?>"><img class="artist-avatar" src="<?=e(artist_image_url($a['image_path']))?>" alt=""><div><h3><?=e($a['name'])?></h3><p><?=e((string)$a['track_count'])?> tracks</p></div></a><?php endforeach;?></div><?php if(!$artists):?><div class="panel empty-state"><img src="<?=e(url('assets/images/artist-placeholder.svg'))?>" alt=""><p>No artists have been added yet.</p></div><?php endif;?><?php layout_footer();
